// 1. Retrieve the array of all 15 messy items from the previous node
const items = $input.all();

// 2. Use .map() to loop through and clean every record
const processedItems = items.map(item => {
    const rawName = item.json.name || "";
    const rawEmail = item.json.email || "";
    const score = item.json.score || 0;

    // A. Normalize Name: Trim spaces, make lowercase, then capitalize the first letter of each word (Title Case)
    const cleanName = rawName
        .trim()
        .toLowerCase()
        .split(' ')
        .filter(word => word.length > 0) // removes double spaces
        .map(word => word.charAt(0).toUpperCase() + word.slice(1))
        .join(' ');

    // B. Normalize Email: Trim spaces and make entirely lowercase
    const cleanEmail = rawEmail.trim().toLowerCase();

    // C. Compute Grade based on numeric score
    let grade = 'F';
    if (score >= 90) {
        grade = 'A';
    } else if (score >= 80) {
        grade = 'B';
    } else if (score >= 70) {
        grade = 'C';
    } else if (score >= 60) {
        grade = 'D';
    }

    // Return the newly cleaned object, keeping the strict n8n { json: {} } structure
    return {
        json: {
            name: cleanName,
            email: cleanEmail,
            score: score,
            grade: grade
        }
    };
});

// 3. Use .filter() to keep ONLY records where the grade is A or B (Grade >= B)
const topStudents = processedItems.filter(item => {
    return item.json.grade === 'A' || item.json.grade === 'B';
});

// 4. Return the final filtered list to output to the next node
return topStudents;
